static String generateLink(Map<String, Path> strony, String fromPage, String toPage) {
    Path from = strony.get(fromPage);
    Path to = strony.get(toPage);
    return from.getParent().relativize(to).toString();
}

static Path safeResolve(Path base, String userInput) {
    Path wynik = base.resolve(userInput).normalize();
    if (!wynik.startsWith(base.normalize())) {
        throw new SecurityException("Sciezka wychodzi poza dozwolony katalog: " + wynik);
    }
    return wynik;
}

