static boolean matches(Path pattern, Path actual) {
    if (pattern.getNameCount() != actual.getNameCount()) return false;
    for (int i = 0; i < pattern.getNameCount(); i++) {
        String p = pattern.getName(i).toString();
        if (!p.equals("*") && !p.equals(actual.getName(i).toString())) {
            return false;
        }
    }
    return true;
}

static boolean hasDuplicateSegment(Path path) {
    Set<String> widziane = new HashSet<>();
    for (Path segment : path) {
        if (!widziane.add(segment.toString())) {
            return true;
        }
    }
    return false;
}

static Path resolvePath(String base, String... segments) {
    return Path.of(base, segments);
}

static boolean normalizedEquals(Path a, Path b) {
    return a.normalize().equals(b.normalize());
}

static Path relativeLink(Path from, Path to) {
    return from.relativize(to);
}
